const API_BASE_URL = 'http://localhost:5001/api';

export interface EnrollmentPrediction {
  children_enrollment: number;
  adult_enrollment: number;
  total_enrollment: number;
  input: any;
}

export interface ClassificationResult {
  prediction: 'high' | 'low';
  probability: number;
  confidence: number;
}

export interface AnomalyDetection {
  is_anomaly: boolean;
  anomaly_score: number;
  status: 'anomaly' | 'normal';
}

export interface ClusterResult {
  cluster: number;
  total_clusters: number;
}

export interface ComprehensiveAnalysis {
  enrollment: {
    children: number;
    adults: number;
    total: number;
  };
  classification: {
    prediction: 'high' | 'low';
    probability: number;
  };
  anomaly: {
    is_anomaly: boolean;
    score: number;
    status: 'anomaly' | 'normal';
  };
  cluster: {
    id: number;
    total_clusters: number;
  };
}

export interface DashboardStats {
  summary: {
    total_enrollments: number;
    total_children: number;
    total_adults: number;
    num_states: number;
    num_districts: number;
    num_pincodes: number;
    avg_enrollment_per_pincode: number;
    median_enrollment: number;
    anomaly_percentage: number;
    high_enrollment_areas: number;
    low_enrollment_areas: number;
  };
  state_stats: any;
}

async function apiRequest<T>(endpoint: string, options?: RequestInit): Promise<T> {
  const url = `${API_BASE_URL}${endpoint}`;
  const response = await fetch(url, {
    headers: {
      'Content-Type': 'application/json',
      ...options?.headers,
    },
    ...options,
  });

  if (!response.ok) {
    const error = await response.json();
    throw new Error(error.error || 'API request failed');
  }

  return response.json();
}

export const api = {
  health: () => apiRequest<{ status: string; timestamp: string }>('/health'),
  
  getStates: () => apiRequest<{ states: string[] }>('/states'),
  
  getDistricts: () => apiRequest<{ districts: string[] }>('/districts'),
  
  getDistrictsForState: (state: string) => 
    apiRequest<{ state: string; districts: string[] }>(`/districts/${encodeURIComponent(state)}`),
  
  getStats: () => apiRequest<DashboardStats>('/stats'),
  
  predictEnrollment: (data: any) => 
    apiRequest<EnrollmentPrediction>('/predict/enrollment', {
      method: 'POST',
      body: JSON.stringify(data),
    }),
  
  classifyEnrollment: (data: any) =>
    apiRequest<ClassificationResult>('/classify/enrollment', {
      method: 'POST',
      body: JSON.stringify(data),
    }),
  
  detectAnomaly: (data: any) =>
    apiRequest<AnomalyDetection>('/detect/anomaly', {
      method: 'POST',
      body: JSON.stringify(data),
    }),
  
  predictCluster: (data: any) =>
    apiRequest<ClusterResult>('/cluster', {
      method: 'POST',
      body: JSON.stringify(data),
    }),
  
  analyze: (data: any) =>
    apiRequest<ComprehensiveAnalysis>('/analyze', {
      method: 'POST',
      body: JSON.stringify(data),
    }),
};